import{z as l,x as i,o as e,c as d,q as r,j as t,D as E,d as n,s as A,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"跨市场套利的制度约束","description":"","frontmatter":{"title":"跨市场套利的制度约束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gm-arb-constraints.md","filePath":"quant/gm-arb-constraints.md","lastUpdated":1791063341000}'),m={name:"quant/gm-arb-constraints.md"};function p(C,a,F,c,h,u){const o=i("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="跨市场套利的制度约束" tabindex="-1">跨市场套利的制度约束 <a class="header-anchor" href="#跨市场套利的制度约束" aria-label="Permalink to &quot;跨市场套利的制度约束&quot;">​</a></h1><div class="epigraph"><p>同一种资产在两个市场的价差，先别叫非理性：时钟、日历、税、资本与结算各收一道过路费——价差是摩擦的定价，能把过路费算清的人才轮得到谈收敛。</p><footer>—— 据 Froot and Dabora, Journal of Financial Economics, 1999；Makarov and Schoar, 2020；Gromb and Vayanos, 2010 整理</footer></div><p><a href="/quant/gm-tax-costs">上一课</a>把税写成行为的函数。本课把前面所有机制拧到同一个问题上是：同一风险资产在两个制度下的折溢价——存托凭证对本地股、ETF 对一篮子、南北向对本地、跨所加密对。套利理论说价差该被抹平；本课程前八课列出的每一条制度，恰好都是抹平机器上的一颗砂。本课把砂粒收成一张可操作的摩擦清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>折溢价文献的老结论先摆正：贴近到只差国界的双上市价差可以长期存在且随情绪波动（Froot and Dabora 1999），资本管制下的跨所加密价差在管制期持续且宽（Makarov and Schoar 2020）——「一价律」的失效不是 anomalies 清单上的怪事，而是制度摩擦的常规输出。缺口是操作面的：拿到一个跨市场价差，先判断它是机会还是状态变量。判据不是价差宽度，而是摩擦清单能否通过。清单七项：一，时钟重叠——两边不同时开市，价差在任一时点只对一边可执行；二，日历——假日错位天是纯敞口天（<a href="/quant/gm-hongkong">香港市场</a>的通道错位是标准样本）；三，结算差——周期不同步把敞口拉长（<a href="/quant/gm-clearing-settlement">清算与结算</a>的周期差口径）；四，税与预扣——往返两腿的税负从价差里直接扣（<a href="/quant/gm-tax-costs">税与交易成本</a>的三层账）；五，资本通道——额度、许可与汇兑限制决定「钱能不能过去」，通道关闭时价差失去收敛机制；六，做空可得性——空腿借不到，价差只能单边收；七，数据时戳——两边「收盘」的定义不同，用对方收盘对本方开盘对齐时，把过时价差误当信息。</p><p><span class="marginnote">先核通道，再核价差：资本管制下的「便宜腿」在你无法把钱汇过去时不是机会，是别人价差表的注释——五、六两项决定价差可不可以做，前三项决定做了要背多少敞口。</span></p><p><span class="marginnote">「机会还是状态变量」可以想象成天气：一张台风警报前的低价机票，对能改签的人是折扣、对不能改签的人是陷阱。同一个折价数字，随你手里有没有「通道与借券」这些伞而改变性质——所以清单第一问永远不是「价差多宽」，而是「我能过吗」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建模上把价差对摩擦回归，而不是对情绪回归。做法：对每一对配对腿建七项摩擦的时变表（通道开闭、借券费、税费、日历、时戳规则），把折溢价作为被解释变量；通过项数与摩擦成本能解释的份额，才是留给「行为」的部分。敞口管理上按「两边同时可交易且都已最终结算」的时间片计持仓，日历错位天用期货或近似腿替代对冲并单列替代误差。执行上把摩擦成本折成盈亏平衡价差宽度：价差必须宽过「税 + 借券费 + 两腿成本 + 汇兑与提币摩擦」的往返总和才开始有意义——这与费用调整后的经济价差是同一算法（<a href="/quant/maker-taker">maker-taker</a>），只是腿加到了两条以上。</p><p><span class="marginnote">数字实例：设 A 股市场价 102、B 市场价 100。往返要付：卖出腿印花税 0.1%、两腿各 0.05% 佣金、借券费年化 6% 折 3 天约 0.05%、汇兑与提币摩擦 0.3%，合计约 0.55%，即约 0.55 元。价差只有 2 元里能落袋约 1.45 元，再扣掉日历错位天的对冲误差——表面 2% 的价差可能只值半个百分点。</span></p>',10)),(e(),t(s,null,{default:E(()=>[A(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E8%B7%A8%E5%B8%82%E5%9C%BA%E4%BB%B7%E5%B7%AE%22%5D%20--%3E%20F%5B%22%E4%B8%83%E9%A1%B9%E6%91%A9%E6%93%A6%E6%B8%85%E5%8D%95%22%5D%0A%20%20F%20--%3E%20G%7B%22%E9%80%9A%E9%81%93%E4%B8%8E%E4%B8%A4%E8%85%BF%E9%83%BD%E5%8F%AF%E8%A1%8C%3F%22%7D%0A%20%20G%20--%3E%7C%22%E6%98%AF%22%7C%20T%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%EF%BC%9A%E6%8C%89%E6%95%9E%E5%8F%A3%E7%89%87%E5%AF%B9%E5%86%B2%22%5D%0A%20%20G%20--%3E%7C%22%E5%90%A6%22%7C%20N%5B%22%E7%8A%B6%E6%80%81%E5%8F%98%E9%87%8F%EF%BC%9A%E5%8F%AA%E8%A7%82%E5%AF%9F%E4%B8%8D%E4%BA%A4%E6%98%93%22%5D%0A%20%20T%20--%3E%20E%5B%22%E7%9B%88%E4%BA%8F%E5%B9%B3%E8%A1%A1%E5%AE%BD%E5%BA%A6%EF%BC%9A%E7%A8%8E%2B%E8%B4%B9%2B%E5%80%9F%E5%88%B8%2B%E6%B1%87%E5%85%91%22%5D%0A%20%20E%20--%3E%20D%7B%22%E4%BB%B7%E5%B7%AE%E5%AE%BD%E8%BF%87%E5%B9%B3%E8%A1%A1%E7%82%B9%3F%22%7D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20X%5B%22%E5%BB%BA%E4%BB%93%E5%B9%B6%E6%8C%89%E6%97%A5%E5%8E%86%E7%AE%A1%E7%90%86%E6%95%9E%E5%8F%A3%22%5D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20W%5B%22%E7%AD%89%E5%BE%85%EF%BC%9A%E6%91%A9%E6%93%A6%E6%9C%AA%E8%BF%87%E8%B7%AF%E8%B4%B9%E7%BA%BF%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[n("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"摩擦的机制特点是方向性与状态性。方向性：多数摩擦只挡单程——买入便宜腿容易、把钱汇回来难，于是价差在「容易的方向」先收敛、在「难的方向」滞留，折溢价呈现持续偏移而不是对称噪声。状态性：通道与借券是状态变量，价差的「可交易性」随状态翻转——同一个折价数字，通道开时是套利、通道关时是陷阱，这正是套利限制理论（Gromb and Vayanos 2010）的制度版：摩擦大时，收窄价差的资本本身被摩擦挡在门外。时戳的机制最隐蔽：跨时区对齐永远在做「用旧信息对新信息」的配对，回归出的领先滞后一部分是制度时差的机械产物。不这么做会错在哪：把折溢价直接当均值回复信号做回归，样本里的「回复」可能全部来自通道重开事件——回复的不是价格是状态。",-1)),a[5]||(a[5]=B("p",null,"「钱能进不能出」这条单向阀如何制造持续折价，回答的是「价差为什么偏向一侧滞留」：",-1)),(e(),t(s,null,{default:E(()=>[A(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20Cheap%5B%22%E4%BE%BF%E5%AE%9C%E8%85%BF%20%E6%9C%AC%E5%9C%B0%E5%B8%82%E5%9C%BA%22%5D%20--%3E%7C%22%E4%B9%B0%E5%85%A5%20%E9%80%9A%E9%81%93%E5%85%81%E8%AE%B8%22%7C%20Exp%5B%22%E8%B4%B5%E8%85%BF%20%E5%AD%98%E6%89%98%E5%87%AD%E8%AF%81%22%5D%0A%20%20Exp%20--%3E%7C%22%E5%8D%96%E5%87%BA%E5%AE%B9%E6%98%93%22%7C%20Cash%5B%22%E8%B5%84%E9%87%91%E8%90%BD%E5%9C%B0%22%5D%0A%20%20Cash%20--%3E%7C%22%E6%B1%87%E5%9B%9E%20%E8%A2%AB%E7%AE%A1%E5%88%B6%E6%8C%A1%E4%BD%8F%22%7C%20Blocked%5B%22%E8%B5%84%E9%87%91%E6%BB%9E%E7%95%99%22%5D%0A%20%20Blocked%20-.-%3E%7C%22%E6%97%A0%E6%B3%95%E5%9B%9E%E8%A1%A5%E5%A5%97%E5%88%A9%E8%B5%84%E6%9C%AC%22%7C%20Cheap%0A%20%20Exp%20--%3E%20V%5B%22%E6%8A%98%E4%BB%B7%E6%BB%9E%E7%95%99%E5%9C%A8%E8%B4%B5%E8%85%BF%E4%B8%80%E4%BE%A7%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">常见误区：初学者容易把折溢价收窄直接当成「均值回复信号」做统计套利。实际上样本里的每次回复可能都对应一次「通道重开」的政策事件——回复的是通道状态，不是价格本身有引力。通道关闭期间加仓，等于在单向阀堵住时继续往里灌水。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写监管套利与规避通道——把合规通道的额度绕开的做法不在允许集里，与另类数据课对「违规信息」的口径一致。外汇对冲的成本与基差不展开（货币侧另有课程）。加密腿的提币与法币腿的 T+n 不是同一时间单位，配对时按保守侧取敞口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跨市场折溢价的第一分类是「机会还是状态变量」，判据是七项摩擦清单。</li><li>通道与做空可得性决定可不可以做；时钟、日历、结算差决定背多少敞口。</li><li>盈亏平衡宽度把税、费、借券与汇兑折成一条过路费线，价差宽过它才有意义。</li><li>摩擦有方向与状态：价差收敛可能来自通道事件，不是均值回复。</li><li>出处：Froot and Dabora, <em>Journal of Financial Economics</em>, 1999；Makarov and Schoar, 2020；Gromb and Vayanos, <em>Annual Review of Financial Economics</em>, 2010。</li></ul>',5))])}const b=l(m,[["render",p]]);export{f as __pageData,b as default};
